function barcodeValue(int $id,string $sku=''):string{return $sku!==''?$sku:sprintf('BM-%08d',$id);}
function code39Svg(string $value):string{
 $map=['0'=>'nnnwwnwnn','1'=>'wnnwnnnnw','2'=>'nnwwnnnnw','3'=>'wnwwnnnnn','4'=>'nnnwwnnnw','5'=>'wnnwwnnnn','6'=>'nnwwwnnnn','7'=>'nnnwnnwnw','8'=>'wnnwnnwnn','9'=>'nnwwnnwnn','A'=>'wnnnnwnnw','B'=>'nnwnnwnnw','C'=>'wnwnnwnnn','D'=>'nnnnwwnnw','E'=>'wnnnwwnnn','F'=>'nnwnwwnnn','G'=>'nnnnnwwnw','H'=>'wnnnnwwnn','I'=>'nnwnnwwnn','J'=>'nnnnwwwnn','K'=>'wnnnnnnww','L'=>'nnwnnnnww','M'=>'wnwnnnnwn','N'=>'nnnnwnnww','O'=>'wnnnwnnwn','P'=>'nnwnwnnwn','Q'=>'nnnnnnwww','R'=>'wnnnnnwwn','S'=>'nnwnnnwwn','T'=>'nnnnwnwwn','U'=>'wwnnnnnnw','V'=>'nwwnnnnnw','W'=>'wwwnnnnnn','X'=>'nwnnwnnnw','Y'=>'wwnnwnnnn','Z'=>'nwwnwnnnn','-'=>'nwnnnnwnw','.'=>'wwnnnnwnn',' '=>'nwwnnnwnn','$'=>'nwnwnwnnn','/'=>'nwnwnnnwn','+'=>'nwnnnwnwn','%'=>'nnnwnwnwn','*'=>'nwnnwnwnn'];
 $v='*'.preg_replace('/[^A-Z0-9. $\/+%-]/','-',strtoupper($value)).'*';$x=10;$bars='';foreach(str_split($v) as $ch){$pat=$map[$ch]??$map['-'];for($i=0;$i<9;$i++){$w=$pat[$i]==='w'?3:1;if($i%2===0)$bars.='<rect x="'.$x.'" y="4" width="'.$w.'" height="48" fill="#000"/>';$x+=$w;} $x+=1;}return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 '.($x+10).' 56" role="img" aria-label="Code-barres '.h($value).'"><rect width="100%" height="100%" fill="#fff"/>'.$bars.'</svg>';
}
function audit(PDO $db,string $action,?string $entity=null,?int $id=null,string $details=''):void { $q=$db->prepare('INSERT INTO audit_log(user_id,action,entity_type,entity_id,details,ip_address) VALUES(?,?,?,?,?,?)'); $q->execute([$_SESSION['user_id']??null,$action,$entity,$id,substr($details,0,500),substr((string)($_SERVER['REMOTE_ADDR']??''),0,64)]); }
function h($v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function setting(PDO $db,string $key,string $default=''):string{$s=$db->prepare('SELECT value FROM settings WHERE key=?');$s->execute([$key]);$v=$s->fetchColumn();return $v===false?$default:(string)$v;}
function csrf():string{if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(32));return $_SESSION['csrf'];}
function verifyCsrf():void{if(empty($_POST)&&(int)($_SERVER['CONTENT_LENGTH']??0)>0){http_response_code(413);exit('Envoi trop volumineux : la taille totale des photos dépasse la limite du serveur (post_max_size = '.ini_get('post_max_size').'). Envoyez moins de photos à la fois ou réduisez leur taille.');}if(!hash_equals($_SESSION['csrf']??'',(string)($_POST['csrf']??''))){http_response_code(419);exit('Jeton de sécurité invalide. Rechargez la page et réessayez.');}}
