function goldPriceAt(PDO $db,string $date,string $currency):?float{$s=$db->prepare('SELECT price_per_gram FROM gold_prices WHERE currency=? AND price_date<=? ORDER BY price_date DESC LIMIT 1');$s->execute([$currency,$date]);$v=$s->fetchColumn();return $v===false?null:(float)$v;}
function csvRow($out,array $row,string $delimiter=';'):void{$safe=[];foreach($row as $v){if(is_string($v)&&preg_match('/^\s*[=+@-]/u',$v))$v="'".$v;$safe[]=$v;}fputcsv($out,$safe,$delimiter);}
const ITEM_CATEGORIES=['Montre','Bague','Chaîne','Bracelet','Boucles d’oreilles','Pendentif','Bijou en or','Diamant / pierres','Autre'];
const MAX_PHOTOS_PER_ITEM=8;
const DORMANT_DEFAULT_DAYS=365;
/** Condition SQL « stock dormant » : ancienneté >= seuil de la catégorie (365 jours par défaut). */
function dormantExpr(string $a='items'):string{return "(julianday(date('now'))-julianday($a.purchase_date))>=COALESCE((SELECT t.days FROM category_thresholds t WHERE t.category=$a.category),".DORMANT_DEFAULT_DAYS.")";}
function dormantThresholds(PDO $db):array{$out=[];foreach($db->query('SELECT category,days FROM category_thresholds') as $r)$out[$r['category']]=(int)$r['days'];return $out;}
function pctFmt(float $v,bool $sign=false):string{return ($sign&&$v>0?'+':'').number_format($v,1,',',' ').' %';}
function appBaseUrl():string{$https=!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off';$host=(string)($_SERVER['HTTP_HOST']??'');if(!preg_match('/^[A-Za-z0-9.\-]+(:\d{1,5})?$/',$host)){$host=preg_replace('/[^A-Za-z0-9.\-]/','',(string)($_SERVER['SERVER_NAME']??'localhost'))?:'localhost';$port=(int)($_SERVER['SERVER_PORT']??0);if($port>0&&!in_array($port,[80,443],true))$host.=':'.$port;}$dir=rtrim(str_replace('\\','/',dirname((string)($_SERVER['SCRIPT_NAME']??'/index.php'))),'/');return ($https?'https':'http').'://'.$host.$dir.'/index.php';}
/** Supprime un fichier photo uniquement s'il porte un nom généré par l'application. */
function deletePhotoFile(string $root,string $path):void{if(preg_match('~^uploads/[a-f0-9]{32}\.(jpg|png|webp)$~',$path)&&is_file($root.'/'.$path))@unlink($root.'/'.$path);}
function photoUploads():array{$out=[];foreach(['photos','photo'] as $key){if(!isset($_FILES[$key]))continue;$f=$_FILES[$key];if(is_array($f['name'])){foreach($f['name'] as $i=>$n)$out[]=['name'=>(string)$n,'tmp_name'=>$f['tmp_name'][$i],'error'=>(int)$f['error'][$i],'size'=>(int)$f['size'][$i]];}else{$out[]=['name'=>(string)$f['name'],'tmp_name'=>$f['tmp_name'],'error'=>(int)$f['error'],'size'=>(int)$f['size']];}}return array_values(array_filter($out,fn($f)=>$f['error']!==UPLOAD_ERR_NO_FILE));}
/** Valide puis enregistre les photos envoyées. $stored reçoit chaque fichier déplacé (nettoyage en cas d'erreur). */
function storeItemPhotos(string $root,array &$stored,int $existing):array{
 $files=photoUploads();if(!$files)return [];
 if($existing+count($files)>MAX_PHOTOS_PER_ITEM)throw new RuntimeException('Maximum '.MAX_PHOTOS_PER_ITEM.' photos par article (déjà '.$existing.').');
 $ok=[];$exts=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];
 foreach($files as $f){$label=' « '.substr(basename($f['name']),0,60).' »';
  if($f['error']!==UPLOAD_ERR_OK)throw new RuntimeException('Le téléversement de la photo'.$label.' a échoué. Vérifiez la taille maximale autorisée par PHP (upload_max_filesize / post_max_size).');
  if(!is_uploaded_file($f['tmp_name']))throw new RuntimeException('Fichier photo non valide.');
  if($f['size']<1||$f['size']>5*1024*1024)throw new RuntimeException('La photo'.$label.' doit peser moins de 5 Mo.');
  $info=@getimagesize($f['tmp_name']);if(!$info||!isset($exts[$info['mime']]))throw new RuntimeException('Format photo accepté : JPG, PNG ou WebP.'.$label);
  $ok[]=[$f['tmp_name'],$exts[$info['mime']]];}
 $new=[];foreach($ok as [$tmp,$ext]){$path='uploads/'.bin2hex(random_bytes(16)).'.'.$ext;if(!move_uploaded_file($tmp,$root.'/'.$path))throw new RuntimeException('Impossible d’enregistrer la photo.');$stored[]=$path;$new[]=$path;}
 return $new;}
/** Journalise un changement de prix de détail daté (ancien prix NULL = prix défini pour la première fois). */
function recordPriceChange(PDO $db,int $itemId,?float $old,float $new,string $cur,string $note=''):void{
 $old=($old!==null&&$old>0)?$old:null;
 if($old===null&&$new<=0)return;if($old!==null&&abs($old-$new)<0.005)return;
 $db->prepare('INSERT INTO price_history(item_id,old_price,new_price,currency,changed_at,changed_by,note) VALUES(?,?,?,?,?,?,?)')->execute([$itemId,$old,$new,$cur,date('Y-m-d'),$_SESSION['user_id']??null,$note!==''?$note:null]);}
/** Variation du cours de l'or sur ~7 jours et impact sur la valeur théorique du métal en stock (même devise uniquement). */
function goldAlert(PDO $db,string $cur,float $thr,?string $today=null):array{
 $today=$today??date('Y-m-d');if($thr<=0)return ['status'=>'off'];
 $q=$db->prepare('SELECT price_date,price_per_gram FROM gold_prices WHERE currency=? ORDER BY price_date DESC LIMIT 1');$q->execute([$cur]);$last=$q->fetch();
 if(!$last)return ['status'=>'nodata','cur'=>$cur];
 if($last['price_date']<date('Y-m-d',strtotime($today.' -7 days')))return ['status'=>'stale','cur'=>$cur,'last'=>$last];
 $q=$db->prepare('SELECT price_date,price_per_gram FROM gold_prices WHERE currency=? AND price_date<=? AND price_date>=? ORDER BY price_date DESC LIMIT 1');
 $q->execute([$cur,date('Y-m-d',strtotime($last['price_date'].' -7 days')),date('Y-m-d',strtotime($last['price_date'].' -10 days'))]);$ref=$q->fetch();
 if(!$ref||(float)$ref['price_per_gram']<=0)return ['status'=>'nodata','cur'=>$cur,'last'=>$last];
 $lp=(float)$last['price_per_gram'];$rp=(float)$ref['price_per_gram'];$change=($lp-$rp)/$rp*100;
 $q=$db->prepare("SELECT COUNT(*) n,COALESCE(SUM(gold_grams*gold_purity/24.0),0) fine FROM items WHERE status='stock' AND gold_price_currency=? AND gold_grams>0 AND gold_purity>0");$q->execute([$cur]);$m=$q->fetch();
 $q=$db->prepare("SELECT COUNT(*) FROM items WHERE status='stock' AND gold_price_currency<>? AND gold_grams>0 AND gold_purity>0");$q->execute([$cur]);$other=(int)$q->fetchColumn();
 $fine=(float)$m['fine'];$days=max(1,(int)round((strtotime($last['price_date'])-strtotime($ref['price_date']))/86400));
 return ['status'=>abs($change)>$thr?'alert':'ok','cur'=>$cur,'change'=>$change,'days'=>$days,'last'=>$last,'ref'=>$ref,'items'=>(int)$m['n'],'fine'=>$fine,'delta'=>$fine*($lp-$rp),'value_now'=>$fine*$lp,'value_ref'=>$fine*$rp,'other'=>$other,'threshold'=>$thr];}
/** Valeur théorique du métal en stock, une ligne par devise du cours (jamais additionnées entre elles). */
function metalByCurrency(PDO $db,string $today):array{
 $out=[];$spots=[];
 foreach($db->query("SELECT gold_price_currency cur,gold_grams,gold_purity FROM items WHERE status='stock' AND gold_grams>0") as $r){$c=$r['cur'];
  if(!isset($out[$c]))$out[$c]=['items'=>0,'valued'=>0,'fine'=>0.0,'value'=>0.0,'nospot'=>0,'nopurity'=>0,'spot'=>null];
  if(!array_key_exists($c,$spots))$spots[$c]=goldPriceAt($db,$today,$c);
  $out[$c]['items']++;$out[$c]['spot']=$spots[$c];$purity=max(0,min(24,(int)$r['gold_purity']));
  if($purity<=0){$out[$c]['nopurity']++;continue;}if($spots[$c]===null){$out[$c]['nospot']++;continue;}
  $fine=(float)$r['gold_grams']*$purity/24;$out[$c]['valued']++;$out[$c]['fine']+=$fine;$out[$c]['value']+=$fine*$spots[$c];}
 ksort($out);return $out;}
/** Rotation du stock par catégorie ou fournisseur, dans UNE devise (pas de conversion). */
function rotationStats(PDO $db,string $col,string $cur,string $today):array{
 if(!in_array($col,['category','supplier'],true))throw new InvalidArgumentException('Colonne inconnue.');
 $m12=date('Y-m-d',strtotime($today.' -365 days'));
 $q=$db->prepare("SELECT COALESCE(NULLIF(TRIM(i.$col),''),'Non renseigné') grp,
  SUM(CASE WHEN i.status='sold' THEN 1 ELSE 0 END) sold_n,
  AVG(CASE WHEN i.status='sold' AND i.sale_date IS NOT NULL THEN julianday(i.sale_date)-julianday(i.purchase_date) END) avg_days,
  SUM(CASE WHEN i.status='sold' THEN i.sale_price ELSE 0 END) revenue,
  SUM(CASE WHEN i.status='sold' THEN i.purchase_price ELSE 0 END) cogs,
  SUM(CASE WHEN i.status='sold' THEN COALESCE((SELECT SUM(c.amount) FROM item_costs c WHERE c.item_id=i.id AND c.currency=i.currency),0) ELSE 0 END) costs,
  SUM(CASE WHEN i.status='stock' THEN 1 ELSE 0 END) stock_n,
  SUM(CASE WHEN i.status='stock' THEN i.purchase_price ELSE 0 END) stock_cap,
  AVG(CASE WHEN i.status='stock' THEN julianday(:today)-julianday(i.purchase_date) END) stock_age,
  SUM(CASE WHEN i.status='sold' AND i.sale_date>=:m12 THEN 1 ELSE 0 END) sold12_n,
  SUM(CASE WHEN i.status='sold' AND i.sale_date>=:m12 THEN i.purchase_price ELSE 0 END) cogs12
  FROM items i WHERE i.currency=:cur GROUP BY grp ORDER BY stock_cap DESC, grp");
 $q->execute([':today'=>$today,':m12'=>$m12,':cur'=>$cur]);$rows=$q->fetchAll();
 foreach($rows as &$r){foreach(['sold_n','stock_n','sold12_n'] as $k)$r[$k]=(int)$r[$k];foreach(['revenue','cogs','costs','stock_cap','cogs12'] as $k)$r[$k]=(float)$r[$k];
  $r['avg_days']=$r['avg_days']!==null?(float)$r['avg_days']:null;$r['stock_age']=$r['stock_age']!==null?(float)$r['stock_age']:null;
  $r['margin']=$r['sold_n']>0?$r['revenue']-$r['cogs']-$r['costs']:null;
  $r['margin_pct']=($r['sold_n']>0&&$r['revenue']>0)?$r['margin']/$r['revenue']*100:null;
  $r['turnover']=$r['stock_cap']>0?$r['cogs12']/$r['stock_cap']:null;
  if($r['stock_n']===0)$r['signal']=['—',''];
  elseif($r['sold12_n']===0)$r['signal']=['Capital immobilisé : aucune vente en 12 mois','text-red'];
  elseif($r['margin']!==null&&$r['margin']<0)$r['signal']=['Marge réelle négative','text-red'];
  elseif($r['turnover']!==null&&$r['turnover']<0.5)$r['signal']=['Rotation lente','text-gold'];
  else $r['signal']=['Rotation correcte','text-green'];}
 unset($r);return $rows;}
/** Articles dormants éligibles à une baisse en lot (devise donnée, prix de détail > 0). Plancher optionnel au coût d'achat. */
function bulkPriceCandidates(PDO $db,string $cat,float $pct,bool $floor,string $cur):array{
 $sql="SELECT id,name,sku,category,purchase_date,purchase_price,retail_price FROM items WHERE status='stock' AND currency=? AND retail_price>0 AND ".dormantExpr();$args=[$cur];
 if($cat!==''){$sql.=' AND category=?';$args[]=$cat;}
 $q=$db->prepare($sql.' ORDER BY purchase_date ASC');$q->execute($args);$apply=[];$skip=[];
 foreach($q->fetchAll() as $r){$old=(float)$r['retail_price'];$r['old']=$old;$r['new']=round($old*(1-$pct/100),2);if($floor&&$r['new']<(float)$r['purchase_price'])$skip[]=$r;else $apply[]=$r;}
 return ['apply'=>$apply,'skip'=>$skip];}
/** Effet des baisses de prix : une baisse « fait vendre » si la vente suit dans $window jours, sans autre changement de prix entre-temps. */
function priceDropEffect(PDO $db,string $cur,string $today,int $window=30):array{
 $q=$db->prepare("SELECT p.id,p.item_id,p.old_price,p.new_price,p.changed_at,i.name,i.sku,i.status,i.sale_date,i.sale_price FROM price_history p JOIN items i ON i.id=p.item_id WHERE i.currency=? ORDER BY p.item_id,p.changed_at,p.id");
 $q->execute([$cur]);$byItem=[];foreach($q as $r)$byItem[(int)$r['item_id']][]=$r;
 $matureLimit=date('Y-m-d',strtotime($today.' -'.$window.' days'));
 $buckets=[['label'=>'Moins de 10 %','lo'=>0,'hi'=>10,'n'=>0,'sold'=>0],['label'=>'10 à 20 %','lo'=>10,'hi'=>20,'n'=>0,'sold'=>0],['label'=>'20 % et plus','lo'=>20,'hi'=>1000,'n'=>0,'sold'=>0]];
 $soldRows=[];$mature=0;$matureSold=0;
 foreach($byItem as $rows){foreach($rows as $k=>$r){
   if($r['old_price']===null||(float)$r['new_price']>=(float)$r['old_price'])continue;
   $sale=($r['status']==='sold'&&$r['sale_date'])?$r['sale_date']:null;
   if($sale!==null&&$r['changed_at']>$sale)continue;
   $pct=((float)$r['old_price']-(float)$r['new_price'])/(float)$r['old_price']*100;
   $next=$rows[$k+1]['changed_at']??null;$limit=date('Y-m-d',strtotime($r['changed_at'].' +'.$window.' days'));
   $conv=$sale!==null&&$sale>=$r['changed_at']&&$sale<=$limit&&($next===null||$sale<$next);
   if($r['changed_at']<=$matureLimit){$mature++;if($conv)$matureSold++;foreach($buckets as &$b){if($pct>=$b['lo']&&$pct<$b['hi']){$b['n']++;if($conv)$b['sold']++;break;}}unset($b);}
   if($sale!==null){$prev=$soldRows[$r['item_id']]??null;if($prev===null||$r['changed_at']>=$prev['changed_at'])$soldRows[$r['item_id']]=['item_id'=>$r['item_id'],'name'=>$r['name'],'sku'=>$r['sku'],'changed_at'=>$r['changed_at'],'old'=>(float)$r['old_price'],'new'=>(float)$r['new_price'],'pct'=>$pct,'sale_date'=>$sale,'sale_price'=>(float)$r['sale_price'],'days'=>max(0,(int)((strtotime($sale)-strtotime($r['changed_at']))/86400))];}
 }}
 usort($soldRows,fn($a,$b)=>strcmp($b['sale_date'],$a['sale_date']));
 return ['mature'=>$mature,'mature_sold'=>$matureSold,'buckets'=>$buckets,'sold_rows'=>$soldRows,'window'=>$window];}
