if($page==='price-history-export'){header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="historique-prix.csv"');$out=fopen('php://output','w');fwrite($out,"\xEF\xBB\xBF");fputcsv($out,['date','reference','article','categorie','devise','ancien_prix','nouveau_prix','variation_pct','note','statut','date_vente','prix_vente'],';');foreach($db->query("SELECT p.changed_at,i.sku,i.name,i.category,p.currency,p.old_price,p.new_price,p.note,i.status,i.sale_date,i.sale_price FROM price_history p JOIN items i ON i.id=p.item_id ORDER BY p.changed_at,p.id") as $r){$vp=($r['old_price']!==null&&(float)$r['old_price']>0)?round(((float)$r['new_price']-(float)$r['old_price'])/(float)$r['old_price']*100,1):'';csvRow($out,[$r['changed_at'],$r['sku'],$r['name'],$r['category'],$r['currency'],$r['old_price'],$r['new_price'],$vp,$r['note'],$r['status'],$r['sale_date'],$r['sale_price']],';');}fclose($out);exit;}
if($page==='aging-export'){$rows=$db->query("SELECT * FROM items WHERE status='stock' ORDER BY purchase_date ASC")->fetchAll();header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="rapport-stock-dormant.csv"');$out=fopen('php://output','w');fwrite($out,"\xEF\xBB\xBF");fputcsv($out,['reference','article','categorie','marque','date_achat','jours_en_stock','niveau_priorite','prix_achat','devise_achat','poids_or_g','purete_karats','cours_or_par_g','devise_cours_or','valeur_theorique_metal','ecart_metal_vs_achat','action_suggeree','seuil_dormant_jours','dormant'],';');$th=dormantThresholds($db);foreach($rows as $r){$days=max(0,(int)((strtotime($today)-strtotime($r['purchase_date']))/86400));$thr=$th[$r['category']]??DORMANT_DEFAULT_DAYS;$dorm=$days>=$thr?'oui':'non';$tier=$days>=1825?'5 ans et +':($days>=1095?'3 à 5 ans':($days>=365?'1 à 3 ans':'Moins d’un an'));$spot=goldPriceAt($db,$today,$r['gold_price_currency']);$fine=(float)$r['gold_grams']*max(0,min(24,(int)$r['gold_purity']))/24;$metal=($spot!==null&&$fine>0)?$spot*$fine:null;$gap=($metal!==null&&$r['gold_price_currency']===$r['currency'])?$metal-(float)$r['purchase_price']:null;$action=$days>=1825?'Reevaluation prioritaire':($days>=1095?'Preparer une promotion':($days>=365?'Reviser le prix':'Suivi normal'));csvRow($out,[$r['sku'],$r['name'],$r['category'],$r['brand'],$r['purchase_date'],$days,$tier,$r['purchase_price'],$r['currency'],$r['gold_grams'],$r['gold_purity'],$spot,$r['gold_price_currency'],$metal,$gap,$action,$thr,$dorm],';');}fclose($out);exit;}
