<?php if($session):?><article class="panel"><div class="panel-heading"><div><h3><?=h($session['title'])?></h3><p class="muted">Statut : <?=h($session['status'])?> · Session #<?=$sid?></p></div><a class="btn subtle" href="index.php?page=stocktake">Toutes les sessions</a></div><?php if($session['status']==='open'):?><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="stocktake_count"><input type="hidden" name="session_id" value="<?=$sid?>"><label class="full-span">Scanner un code-barres ou un QR code, ou saisir le SKU<input name="barcode" autofocus required autocomplete="off" placeholder="Ex. BM-00000001"></label><div><button class="btn primary">Marquer comme compté</button></div></form><?php endif;?><?php $q=$db->prepare('SELECT COUNT(*) FROM stocktake_lines WHERE session_id=?');$q->execute([$sid]);$counted=(int)$q->fetchColumn();$total=(int)$db->query("SELECT COUNT(*) FROM items WHERE status='stock'")->fetchColumn();?><div class="metric-grid"><div class="metric-card"><div class="metric-head">Articles comptés</div><div class="metric-value"><?=$counted?></div></div><div class="metric-card"><div class="metric-head">Articles en stock actuellement</div><div class="metric-value"><?=$total?></div></div><div class="metric-card"><div class="metric-head">À vérifier</div><div class="metric-value"><?=max(0,$total-$counted)?></div></div></div><div class="table-wrap"><table><thead><tr><th>Article</th><th>SKU / Code-barres</th><th>Compté le</th><th>Par</th></tr></thead><tbody><?php $q=$db->prepare('SELECT i.name,i.sku,i.barcode,l.counted_at,u.email FROM stocktake_lines l JOIN items i ON i.id=l.item_id LEFT JOIN users u ON u.id=l.counted_by WHERE l.session_id=? ORDER BY l.counted_at DESC');$q->execute([$sid]);foreach($q as $r):?><tr><td><?=h($r['name'])?></td><td><?=h($r['barcode']?:$r['sku'])?></td><td><?=h($r['counted_at'])?></td><td><?=h($r['email']??'—')?></td></tr><?php endforeach;?></tbody></table></div><?php if($session['status']==='open'):?><article class="panel"><h3>Articles encore à vérifier</h3><div class="table-wrap"><table><thead><tr><th>Article</th><th>SKU / Code-barres</th><th>Prix payé</th></tr></thead><tbody><?php $q=$db->prepare("SELECT i.name,i.sku,i.barcode,i.purchase_price,i.currency FROM items i WHERE i.status='stock' AND NOT EXISTS (SELECT 1 FROM stocktake_lines l WHERE l.session_id=? AND l.item_id=i.id) ORDER BY i.name LIMIT 200");$q->execute([$sid]);$missingRows=$q->fetchAll();foreach($missingRows as $mr):?><tr><td><?=h($mr['name'])?></td><td><?=h($mr['barcode']?:$mr['sku'])?></td><td><?=money($mr['purchase_price'],$mr['currency'])?></td></tr><?php endforeach;?><?php if(!$missingRows):?><tr><td colspan="3" class="empty">Tous les articles en stock sont comptés.</td></tr><?php endif;?></tbody></table></div><p class="form-help">Affichage limité aux 200 premiers articles non comptés. Les articles retirés du stock pendant la session peuvent nécessiter une vérification manuelle.</p></article><?php endif;?><?php if($session['status']==='open'):?><form method="post" onsubmit="return confirm('Clôturer cette session ?')"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="stocktake_close"><input type="hidden" name="session_id" value="<?=$sid?>"><button class="btn subtle">Clôturer la session</button></form><?php endif;?></article><?php else:?><article class="panel"><h3>Nouvelle session d’inventaire</h3><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="stocktake_start"><label class="full-span">Nom de la session<input name="title" required maxlength="120" value="Inventaire du <?=date('d/m/Y')?>"></label><div><button class="btn primary">Créer une session</button></div></form></article><?php endif;?><article class="panel"><h3>Sessions récentes</h3><div class="table-wrap"><table><thead><tr><th>Session</th><th>Créée le</th><th>Statut</th><th>Progression</th><th></th></tr></thead><tbody><?php foreach($sessions as $ss):?><tr><td><?=h($ss['title'])?></td><td><?=h($ss['created_at'])?></td><td><?=h($ss['status'])?></td><td><?=$ss['counted']?> / <?=$ss['total']?></td><td><a class="btn subtle" href="index.php?page=stocktake&id=<?=$ss['id']?>">Ouvrir</a></td></tr><?php endforeach;?><?php if(!$sessions):?><tr><td colspan="5" class="empty">Aucune session créée.</td></tr><?php endif;?></tbody></table></div></article>
